sources.ActivityPane.ets:
@Component
struct ActivityPane {
 @State activities: string[] = []
 build() {
  Column() {
   List() { ForEach(this.activities, (item: string) => { ListItem() { Text(item) } }) }
   .listDirection(Axis.Vertical).height("100%")
  }
 }
}

