sources.LabelSubmission.ts:
export class LabelSubmission {
 submit(label: string): boolean {
  if (label.trim().length === 0) { return false }
  this.dispatcher.send(label)
  return true
 }
}

sources.DirectDispatcher.ts:
export class DirectDispatcher {
 send(label: string): void {
  this.transport.deliver(label)
 }
}

